&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Imp&#233;rial.html&quot; title=&quot;Les dragons imp&#233;riaux&quot;&gt;dragons imp&#233;riaux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Imp&#233;rial-Des-Mers.html&quot; title=&quot;Dragon imp&#233;rial des mers&quot;&gt;dragons des mers&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Le long corps de ce dragon serpentin ploie et ondule, et ses &#233;cailles ont la
m&#234;me couleur que les vagues de l’oc&#233;an.&lt;/i&gt;
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
